:root{
  color-scheme:dark;--ink:#090c13;--panel:#111622;--paper:#f4f1e9;--muted:#999da9;--accent:#85cfe2;--gold:#d4c4a0;--line:rgba(230,224,210,.16);
  font-family:"Inter","Helvetica Neue","Microsoft YaHei","PingFang SC",sans-serif;font-synthesis:none;
}
*{box-sizing:border-box}
html,body{width:100%;height:100%;margin:0}
body{background:var(--ink);color:var(--paper);overflow:hidden;-webkit-font-smoothing:antialiased}
button,input,select{font:inherit}
button,a,input,select{-webkit-tap-highlight-color:transparent;touch-action:manipulation}
button{border:0;background:none;color:inherit;cursor:pointer}
button:disabled{opacity:.4;cursor:not-allowed}
a{color:inherit;text-decoration:none}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible,.stage:focus-visible{outline:2px solid var(--accent);outline-offset:4px}
svg{display:block}
[hidden]{display:none!important}
::selection{background:var(--accent);color:var(--ink)}
.ambient{position:fixed;inset:0;pointer-events:none;background:radial-gradient(ellipse at 65% -30%,color-mix(in srgb,var(--accent) 10%,transparent),transparent 65%)}
.app{position:relative;height:100svh;min-height:440px;max-width:2600px;margin:0 auto;display:grid;grid-template-rows:96px minmax(0,1fr) 138px;padding:0 32px}
.topbar{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:0 4px}
.wordmark{display:flex;align-items:center;gap:14px;min-width:0}
.wordmark>svg{width:43px;height:43px;color:var(--gold);flex-shrink:0;overflow:visible}
.wordmark b{display:block;font-size:1.375rem;font-weight:600;letter-spacing:.16em;line-height:1.2}
.wordmark small{display:block;margin-top:8px;font-size:.6875rem;letter-spacing:.12em;color:var(--muted);white-space:nowrap}
.wordmark small span{color:var(--gold);margin:0 7px}
.topnav{display:flex;align-items:center;gap:6px;padding:6px;border:1px solid var(--line);border-radius:40px;flex-shrink:0}
.topnav a{font-size:.8125rem;letter-spacing:.04em;padding:12px 20px;color:var(--muted);white-space:nowrap;transition:color .2s}
.topnav a:hover{color:var(--paper)}
.topnav .current{color:var(--ink);background:var(--paper);border-radius:40px}
.top-actions{display:flex;align-items:center;gap:15px}
.icon-button{width:36px;height:42px;display:grid;place-items:center;color:#a7aab3;padding:7px;flex-shrink:0}
.icon-button:hover{color:var(--paper)}
.icon-button svg{width:23px;height:23px;fill:none;stroke:currentColor;stroke-width:1.25}
#settingsOpen circle{fill:var(--ink)}
.auto-button{display:flex;align-items:center;justify-content:center;gap:12px;border:1px solid var(--line);min-height:43px;min-width:125px;padding:10px 16px;font-size:.875rem;letter-spacing:.05em;border-radius:2px;white-space:nowrap;transition:border-color .2s,background .2s}
.auto-button:hover{border-color:#d4c4a066;background:#ffffff05}
#playGlyph{font-size:.6875rem;color:var(--gold);min-width:10px;text-align:center}
.stage{position:relative;isolation:isolate;overflow:hidden;min-height:0;border:1px solid #e6e0d233;border-radius:2px;background:#0b0e1b;touch-action:none;outline:none;box-shadow:0 16px 70px #0003}
#matrixCanvas{position:absolute;inset:0;width:100%;height:100%;display:block}
.image-shade{position:absolute;inset:0;pointer-events:none;background:linear-gradient(90deg,#060a14b5,#060a143d 31%,transparent 61%),linear-gradient(0deg,#040811b8,transparent 27%),linear-gradient(180deg,#03061124,transparent 22%);transition:opacity .3s}
.frame-corner{position:absolute;width:15px;height:15px;border-color:#eee4ceb3;border-style:solid;pointer-events:none;opacity:.5}
.tl{left:0;top:0;border-width:1px 0 0 1px}.tr{right:0;top:0;border-width:1px 1px 0 0}.bl{left:0;bottom:0;border-width:0 0 1px 1px}.br{right:0;bottom:0;border-width:0 1px 1px 0}
.stage-head{position:absolute;left:3%;top:30px;display:flex;align-items:center;gap:12px;font-size:.6875rem;letter-spacing:.12em;color:#e6e2d5cc;text-shadow:0 2px 10px #000;pointer-events:none}
.tag-line{width:28px;height:1px;background:var(--gold)}
.stage-head b{font-size:.6875rem;font-weight:400;padding-left:13px;border-left:1px solid #ffffff40;letter-spacing:.08em;color:#c4c6ce}
.specimen-card{position:absolute;right:2.6%;top:28px;width:244px;padding:15px 17px;background:#101625c9;backdrop-filter:blur(14px);-webkit-backdrop-filter:blur(14px);border:1px solid #ebe5d733;border-radius:2px;pointer-events:none}
.specimen-head{display:flex;align-items:center;gap:8px;font-size:.8125rem;letter-spacing:.045em}
.signal-dot{width:4px;height:4px;background:var(--accent);border-radius:50%;box-shadow:0 0 8px var(--accent);flex-shrink:0}
.telemetry-star{margin-left:auto;color:var(--accent);font-size:1.375rem;line-height:1}
.hairline{height:1px;background:#ffffff22;margin:16px 0 12px}
.specimen-foot{display:flex;justify-content:space-between;gap:8px;font-family:ui-monospace,Consolas,monospace;font-size:.625rem;letter-spacing:.02em;color:#c4c7d2}
.hero-copy{position:absolute;left:4.4%;bottom:13%;max-width:55%;color:var(--paper);text-shadow:0 3px 24px #0005;pointer-events:none}
.eyebrow{display:flex;align-items:center;gap:15px;font-family:ui-monospace,Consolas,monospace;font-size:.6875rem;letter-spacing:.14em;margin-bottom:22px;color:#e6dfd8}
.eyebrow-line{width:46px;height:1px;background:var(--accent);opacity:.8}
#stageNumber{color:var(--accent);white-space:nowrap}
.hero-copy h1{margin:0;font-family:"Noto Serif CJK SC","Songti SC","STSong","SimSun",serif;font-size:clamp(36px,3.35vw,64px);font-weight:400;letter-spacing:.07em;line-height:1.47}
.hero-copy h1 span{display:block}
.hero-copy p{font-size:1rem;color:#f9f6eed4;letter-spacing:.055em;margin:22px 0 0;line-height:1.85;max-width:38em}
.hero-actions{display:flex;align-items:center;gap:28px;margin-top:30px}
.hero-actions button{pointer-events:auto}
.next-hero{display:flex;align-items:center;gap:25px;padding:0;font-size:.875rem;letter-spacing:.09em}
.circle-arrow{width:39px;height:39px;display:grid;place-items:center;border:1px solid #f8eed799;border-radius:50%;font-size:1.1875rem;line-height:1;letter-spacing:0;transition:background .2s,color .2s,transform .2s}
.next-hero:hover .circle-arrow{background:var(--paper);color:var(--ink);transform:translate(2px,-2px)}
.bridge-card{display:flex;align-items:center;gap:12px;font-size:.75rem;color:#dfded6ba;padding:10px 0;border-bottom:1px solid #ffffff30;letter-spacing:.035em;transition:color .2s,border-color .2s}
.bridge-card:hover,.bridge-card[aria-pressed=true]{color:var(--paper);border-color:var(--accent)}
#bridgeArrow{color:var(--accent);font-size:1rem}
.scene-rail{position:absolute;right:22px;top:48%;display:flex;flex-direction:column;gap:5px}
.rail-dot{display:grid;place-items:center;width:30px;height:30px;padding:0}
.rail-dot span{width:4px;height:4px;background:#f8f0dd99;transform:rotate(45deg);transition:width .2s,height .2s,background .2s;box-shadow:0 0 8px #10121a}
.rail-dot.active span{width:8px;height:8px;background:var(--accent)}
.rail-dot:hover span{background:white;width:7px;height:7px}
.stage-bottom{position:absolute;left:3%;right:2.6%;bottom:24px;display:flex;align-items:center;justify-content:space-between;gap:20px;pointer-events:none;color:#eee8ddd1;text-shadow:0 2px 10px #000}
.bottom-credit{font: .625rem ui-monospace,Consolas,monospace;letter-spacing:.09em}
.bottom-credit>span{color:var(--accent);margin:0 16px}
.bottom-credit b{font-weight:400;letter-spacing:.04em}
.motion-note{display:flex;align-items:center;gap:11px;font-size:.6875rem;letter-spacing:.065em}
.motion-note svg{width:12px;height:20px;fill:none;stroke:currentColor;stroke-width:.9}
.motion-note i{font-style:normal;opacity:.5;padding:0 7px}
.manual-indicator{position:absolute;left:50%;top:28px;transform:translateX(-50%);padding:10px 16px;border:1px solid #ffffff24;border-radius:40px;background:#050911b8;backdrop-filter:blur(10px);font-size:.75rem;color:#e5e0d6;white-space:nowrap;pointer-events:none}
.manual-indicator span{color:var(--gold);padding:0 6px}
.bottom-bar{display:grid;grid-template-columns:174px minmax(0,1fr) 116px;align-items:center;gap:30px;padding:7px 4px 0;min-width:0}
.sequence-meta{display:flex;flex-direction:column;gap:10px;min-width:0}
.tiny-label{font-family:ui-monospace,Consolas,monospace;font-size:.625rem;letter-spacing:.13em;color:var(--gold)}
.sequence-meta strong{font-family:Georgia,serif;font-weight:400;font-size:2.25rem;line-height:1}
.sequence-meta strong span{font-family:ui-monospace,Consolas,monospace;font-size:.8125rem;color:var(--muted);margin-left:14px}
.folio-note{font-size:.75rem;letter-spacing:.08em;color:var(--muted)}
.filmstrip-wrap{min-width:0}
.timeline-row{display:flex;gap:13px;align-items:center;font-family:ui-monospace,Consolas,monospace;font-size:.625rem;color:var(--muted);margin:0 0 12px}
.timeline-row>span{width:34px;flex-shrink:0}
.timeline-row>span:last-child{text-align:right}
.timeline-track{flex:1;position:relative;height:22px;min-width:0}
.timeline-track:before,.timeline-fill{position:absolute;left:0;right:0;top:10px;height:1px;background:var(--line)}
.timeline-track:before{content:""}
.timeline-fill{background:var(--accent);transform:scaleX(0);transform-origin:left;box-shadow:0 0 10px color-mix(in srgb,var(--accent) 25%,transparent)}
#timeline{position:absolute;inset:0;width:100%;height:22px;min-width:0;margin:0;appearance:none;-webkit-appearance:none;background:transparent;cursor:ew-resize}
#timeline::-webkit-slider-runnable-track{height:1px;background:transparent}
#timeline::-webkit-slider-thumb{-webkit-appearance:none;width:8px;height:8px;border-radius:0;background:var(--accent);border:1px solid var(--paper);transform:rotate(45deg);margin-top:-3.5px}
#timeline::-moz-range-track{height:1px;background:transparent}
#timeline::-moz-range-thumb{width:7px;height:7px;border:1px solid var(--paper);border-radius:0;background:var(--accent);transform:rotate(45deg)}
.filmstrip{display:grid;grid-template-columns:repeat(var(--scene-count,5),minmax(0,1fr));gap:18px}
.film-item{display:flex;align-items:center;gap:12px;text-align:left;padding:0;min-width:0;opacity:.47;transition:opacity .2s,transform .2s}
.film-item:hover{opacity:.85;transform:translateY(-2px)}
.film-item.active{opacity:1}
.film-item img{width:72px;height:44px;object-fit:cover;border:1px solid var(--line);padding:2px;flex-shrink:0;filter:saturate(.7)}
.film-item.active img{border-color:var(--accent);filter:saturate(1)}
.film-item>span{display:flex;flex-direction:column;gap:7px;min-width:0}
.film-item strong{font-size:.875rem;letter-spacing:.04em;font-weight:400;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.film-item small{font-family:ui-monospace,Consolas,monospace;font-size:.625rem;color:var(--muted);white-space:nowrap}
.film-item.active small{color:var(--accent)}
.transport-controls{display:flex;flex-direction:column;align-items:flex-end;gap:15px}
.transport-buttons{display:flex;gap:10px}
.transport-buttons button{width:46px;height:38px;border:1px solid var(--line);font-size:1.5rem;line-height:1;transition:background .2s,border-color .2s}
.transport-buttons button:hover{border-color:var(--accent);background:#ffffff08}
.transport-controls>span{font-size:.625rem;color:var(--muted);white-space:nowrap}
kbd{font-family:ui-monospace,Consolas,monospace;font-size:.625rem;border:1px solid var(--line);border-radius:2px;padding:2px 4px;color:#b3b5bd;margin-right:5px}
